px 50px #153e5555;border:1px solid #f4ecc456}.intro p,.result p{font-size:12px;letter-spacing:.13em;font-weight:800;color:#b7dedf;margin:0 0 10px}h2{font:750 clamp(30px,4vw,48px)/1.06 system-ui;letter-spacing:-.04em;margin:0 0 20px;color:#fff9e7}.start{background:#ffd376;color:#17394a;border:0;border-radius:11px;font-size:19px;font-weight:800;min-height:55px;padding:12px 34px;cursor:pointer;box-shadow:0 5px 0 #b8793e}.intro>span,.result>span{display:block;font-size:14px;color:#d8e9e8;margin:17px 0 0}.result>strong{display:block;font-size:42px;color:#ffdb85;line-height:1.25;margin-bottom:10px}.result strong small{display:block;font-size:16px;font-weight:500}.result .start{margin-top:20px}.bottom{position:absolute;left:24px;right:24px;bottom:22px;display:flex;align-items:center;justify-content:space-between;pointer-events:none;gap:12px}.bottom p{margin:0;border-radius:18px;background:#153f50e6;padding:10px 16px;font-weight:650;font-size:14px;box-shadow:0 2px 8px #0002}.bottom p span{margin-left:20px;color:#f7d8bd}.jump{pointer-events:auto;min-width:145px;min-height:62px;background:#fcf0cc;color:#123849;border:0;border-radius:12px;font-size:20px;font-weight:800;box-shadow:0 5px 0 #a57a50;cursor:pointer;touch-action:manipulation}.jump kbd{font:12px system-ui;display:block;color:#5a6c6d}.jump:disabled{opacity:.5}.progress{position:absolute;bottom:0;left:0;right:0;height:6px;background:#16374d}.progress i{height:100%;display:block;background:#ffd374}footer{height:48px;padding:10px 28px;display:flex;align-items:center;justify-content:space-between;gap:12px;color:#a8c8d4;font-size:12px}footer a{color:#d1e7df;text-underline-offset:3px}button,a{ -webkit-tap-highlight-color:transparent}button:focus-visible,a:focus-visible{outline:3px solid #fff;outline-offset:3px}@media(max-width:650px){header{height:64px;padding:0 16px}header>a span{display:none}h1{font-size:20px}h1 span{display:block;font-size:12px;margin:0;color:#b8dbe0}.planner{font-size:14px}.playfield{height:calc(100dvh - 106px);min-height:480px}.hud{top:14px;left:12px;right:12px;gap:7px;flex-wrap:wrap}.hud>div{padding:9px 11px;min-width:0}.hud span{font-size:12px}.hud strong{font-size:22px}.hud .pause{padding:7px 13px;min-height:40px;font-size:12px}.intro,.result{left:50%;top:45%;padding:22px;width:86%;max-width:380px}.intro p,.result p{font-size:10px}.intro h2{font-size:34px}.bottom{left:12px;right:12px;bottom:18px;align-items:end}.bottom p{font-size:12px;padding:8px 12px}.bottom p span{display:block;margin:4px 0 0}.jump{min-width:120px;min-height:62px}footer{height:42px;padding:7px 14px;font-size:11px}footer>span:first-child{display:none}.collection{margin:0}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important}}
